contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256[] calldata winners) public {
        require(winners.length == c.winnersPerPeriod());
        uint256 roundBefore = c.roundId();
        bool alreadySelectedBefore = c.isSelectionComplete(roundBefore);
        c.pickWinner(winners);
        bool storedComplete = c.isSelectionComplete(roundBefore);
        uint256 roundAfter = c.roundId();
        address[] memory recorded = c.winnerAddresses(roundBefore);
        // second pick for the same round must now revert
        bool reverted;
        try c.pickWinner(winners) { reverted = false; } catch { reverted = true; }
        assert(
            !alreadySelectedBefore &&
            storedComplete &&
            roundAfter == roundBefore + 1 &&
            recorded.length == winners.length &&
            reverted &&
            c.isSelectionComplete(roundAfter) == false
        );
    }
}

