}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 x) public {
        require(x != 0);
        // msg.sender is this contract; make it admin for the grant phase first.
        c.adjustAdminAccess(address(this), true);

        // Admin phase: succeeds and sets value.
        c.updateWinnersPerPeriod(x);
        uint256 afterAdmin = c.winnersPerPeriod();

        // Revoke admin: call must revert and leave value unchanged.
        c.adjustAdminAccess(address(this), false);
        bool reverted;
        try c.updateWinnersPerPeriod(x + 1) { reverted = false; } catch { reverted = true; }
        uint256 afterRevoke = c.winnersPerPeriod();

        assert(reverted && afterAdmin == x && afterRevoke == x);
    }

    receive() external payable {}
}

