contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata winners, uint256 newWinnersPerPeriod) public payable {
        // caller (this contract) is the owner, so it is admin by construction
        c.updateWinnersPerPeriod(newWinnersPerPeriod);
        require(c.winnersPerPeriod() == newWinnersPerPeriod);

        uint256 roundBefore = c.roundId();

        bool revertedWrong;
        if (winners.length != newWinnersPerPeriod) {
            try c.pickWinner(winners) { revertedWrong = false; }
            catch { revertedWrong = true; }
        } else {
            revertedWrong = false;
        }

        bool rule = true;
        if (winners.length != newWinnersPerPeriod) {
            rule = revertedWrong && c.roundId() == roundBefore;
        } else {
            // winners must be existing tokens owned by someone; ownerOf reverts otherwise,
            // so success requires length matches — already ensured — and any revert
            // would come from nonexistent tokens; the rule only claims round advances iff success
            rule = (c.roundId() == roundBefore + 1);
        }
        assert(rule);
    }

    receive() external payable {}
}

